    assert len(d["chs"]) == len(CH_T), (lang, len(d["chs"]), len(CH_T))
    chap = "\n".join(f"{t} {c}" for t, c in zip(CH_T, d["chs"]))
    desc = f"{d['p1']} {d['tags']}\n\n{d['p2']}\n\n{d['ch']}\n{chap}\n\n{d['so']}\n{SOURCES}\n\n{d['cr']}\n\n{d['cf']} · COLD WARRANT"
    open(f"{EP}/dub/{lang}/title.txt", "w", encoding="utf-8").write(d["title"] + "\n")
    open(f"{EP}/dub/{lang}/description.txt", "w", encoding="utf-8").write(desc + "\n")
    print(lang, len(d["title"]), d["title"])
